require __DIR__.'/lib.php';require_login();$lock=null;
try{brand_sku_require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$lock=inventory_write_lock();if(($_POST['action']??'')==='prepare'){$ref=brand_sku_prepare();flash('Backup and restore test passed. Review the saved code mapping.');}elseif(($_POST['action']??'')==='apply'){$ref=$_POST['run']??'';$n=brand_sku_apply($ref,$_POST['digest']??'',$_POST['confirmation']??'',!empty($_POST['review_ack']));flash($n.' item codes updated. Stocks and transaction history preserved.');}else throw new Exception('Invalid action.');inventory_write_unlock($lock);$lock=null;header('Location: index.php?page=brand_sku&run='.urlencode($ref));exit;}
 if(isset($_GET['download'])){$plan=!empty($_GET['run'])?brand_sku_run($_GET['run'])['plan']:brand_sku_plan();$heads=['Product ID','Old Master SKU','New Master SKU','Product Description','Brand','Main Category','Subcategory','Status'];$rows=array_map(fn($l)=>[$l['id'],$l['old'],$l['new'],$l['name'],inventory_filter_brand($l['brand']),$l['main'],$l['sub'],$l['active']?'Active':'Inactive'],$plan['lines']);$meta=['Generated'=>date('Y-m-d H:i:s'),'Generated By'=>current_user()['name'],'Scope'=>'Codes only; no stock reset','Status'=>!empty($_GET['run'])?brand_sku_run($_GET['run'])['status']:'Proposed only'];if(($_GET['format']??'')==='print'){report_print_document('Brand SKU Conversion Mapping',$heads,$rows,$meta);exit;}$path=tempnam(sys_get_temp_dir(),'brand-sku-');try{report_write_xlsx($path,'Brand SKU Conversion',$heads,$rows,$meta);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Brand_SKU_Mapping_'.date('Ymd_His').'.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
 header('Location: index.php?page=brand_sku');exit;
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();inventory_write_unlock($lock);if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(400);echo e(safe_error_message($e));exit;}flash(safe_error_message($e),'danger');header('Location: index.php?page=brand_sku'.(!empty($_POST['run'])?'&run='.urlencode($_POST['run']):''));exit;}
